import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.bijRUqYl.js";const g=JSON.parse('{"title":"通用办公提示词模板","description":"不分行业的 5 条提示词模板：会议纪要、难写的邮件、资料整理、表格、周报汇报。任何岗位都能用。","frontmatter":{"title":"通用办公提示词模板","description":"不分行业的 5 条提示词模板：会议纪要、难写的邮件、资料整理、表格、周报汇报。任何岗位都能用。"},"headers":[],"relativePath":"community/prompts/通用办公.md","filePath":"community/prompts/通用办公.md"}'),e={name:"community/prompts/通用办公.md"};function l(o,s,i,r,c,h){return n(),p("div",null,[...s[0]||(s[0]=[t(`<h1 id="🧰-通用办公-·-5-条提示词模板" tabindex="-1">🧰 通用办公 · 5 条提示词模板 <a class="header-anchor" href="#🧰-通用办公-·-5-条提示词模板" aria-label="Permalink to &quot;🧰 通用办公 · 5 条提示词模板&quot;">​</a></h1><blockquote><p><strong>不分行业。</strong> 这 5 条里，你明天至少能用上一条。 用法：把 <code>【】</code> 换成你自己的，其他照抄。改好一条就存一条。</p></blockquote><h2 id="本行三句话骨架" tabindex="-1">本行三句话骨架 <a class="header-anchor" href="#本行三句话骨架" aria-label="Permalink to &quot;本行三句话骨架&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我是【部门 / 岗位】，正在处理【什么事】。</span></span>
<span class="line"><span>帮我产出一份【交付物】，格式是【…】，长度【…】。</span></span>
<span class="line"><span>按【公司的什么规矩 / 什么样例】来；不确定的地方先问我，别自己猜。</span></span></code></pre></div><hr><h2 id="_1-·-乱糟糟的会议记录-→-能直接转发的纪要" tabindex="-1">1 · 乱糟糟的会议记录 → 能直接转发的纪要 <a class="header-anchor" href="#_1-·-乱糟糟的会议记录-→-能直接转发的纪要" aria-label="Permalink to &quot;1 · 乱糟糟的会议记录 → 能直接转发的纪要&quot;">​</a></h2><p><strong>什么时候用</strong>：开完会，你手上是一堆聊天记录、语音转文字、或者自己随手记的关键词，但你必须发一份纪要出去。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>下面是一次会议的零散记录（可能有错字、重复、跑题）：</span></span>
<span class="line"><span>【粘贴记录】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我整理成一份会议纪要，结构固定为：</span></span>
<span class="line"><span>① 会议主题与时间 ② 参会人 ③ 讨论要点（不超过 5 条）④ 已达成决议 ⑤ 待办清单（表格：事项 / 责任人 / 截止时间）</span></span>
<span class="line"><span>规矩：只写记录里真实出现过的内容，没有的一律标&quot;待确认&quot;，不要替我补。</span></span>
<span class="line"><span>输出用 Markdown，我能直接复制到群里。</span></span></code></pre></div><p><strong>它给你</strong>：一份格式统一的纪要，直接转发。<strong>注意&quot;不要替我补&quot;这句一定要留着</strong>——不加这句，它会帮你编决议。</p><hr><h2 id="_2-·-一封你拖了三天没写的邮件" tabindex="-1">2 · 一封你拖了三天没写的邮件 <a class="header-anchor" href="#_2-·-一封你拖了三天没写的邮件" aria-label="Permalink to &quot;2 · 一封你拖了三天没写的邮件&quot;">​</a></h2><p><strong>什么时候用</strong>：拒绝别人、催款、道歉、向上汇报坏消息——这种邮件最难开头，也最容易越改越软。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我要写一封邮件，收件人是【对方是谁、什么关系】。</span></span>
<span class="line"><span>我要说的事：【一句话说清核心诉求】</span></span>
<span class="line"><span>我的顾虑：【怕得罪人 / 怕显得推卸责任 / 怕对方误会】</span></span>
<span class="line"><span>请给我 2 个版本：</span></span>
<span class="line"><span>① 直白版（先把事说清）</span></span>
<span class="line"><span>② 委婉版（先照顾情绪）</span></span>
<span class="line"><span>两版都要：主题行 + 正文，正文不超过 200 字，结尾给一个明确的下一步动作。</span></span></code></pre></div><p><strong>它给你</strong>：两个版本 + 主题行。<strong>两版对比着看，你自己拼一封最合适的</strong>——比让它&quot;写一封最完美的&quot;好用得多。</p><hr><h2 id="_3-·-一堆散文件-→-一份台账" tabindex="-1">3 · 一堆散文件 → 一份台账 <a class="header-anchor" href="#_3-·-一堆散文件-→-一份台账" aria-label="Permalink to &quot;3 · 一堆散文件 → 一份台账&quot;">​</a></h2><p><strong>什么时候用</strong>：电脑里文件夹乱成一团：合同、发票、照片、各种命名。你要归档、要交接、要找东西。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>下面是我一个文件夹里的文件名清单（有些命名很乱）：</span></span>
<span class="line"><span>【粘贴文件名列表】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我：</span></span>
<span class="line"><span>① 按【业务类型 / 时间 / 客户】三个维度各分一次组；</span></span>
<span class="line"><span>② 给一份重命名规则（用&quot;日期_类型_对象&quot;这种能排序的格式）；</span></span>
<span class="line"><span>③ 列出哪些文件从名字上看不出是什么、需要我打开确认的。</span></span>
<span class="line"><span>先给方案，我确认后再动。</span></span></code></pre></div><p><strong>它给你</strong>：分组方案 + 重命名规则 + 待确认清单。<strong>&quot;先给方案&quot;是关键</strong>——别让它直接改你的文件。</p><hr><h2 id="_4-·-一段话-→-一张能用的表" tabindex="-1">4 · 一段话 → 一张能用的表 <a class="header-anchor" href="#_4-·-一段话-→-一张能用的表" aria-label="Permalink to &quot;4 · 一段话 → 一张能用的表&quot;">​</a></h2><p><strong>什么时候用</strong>：你脑子里有一张表的形状，但懒得从空白表格开始搭。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我要做一张【什么用途】的表格，用 Excel。</span></span>
<span class="line"><span>我手上有的信息是：【把你知道的、哪怕很零散地写出来】</span></span>
<span class="line"><span>这张表主要用来【干什么 / 给谁看】。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请给我：</span></span>
<span class="line"><span>① 列名（每个列名后面写一句这个列该填什么）</span></span>
<span class="line"><span>② 3 行示例数据（假数据，但要像真的）</span></span>
<span class="line"><span>③ 需要自动算的列，给我能直接粘进 Excel 的公式</span></span>
<span class="line"><span>④ 建议加一个什么校验规则，防止填错</span></span></code></pre></div><p><strong>它给你</strong>：列结构 + 假数据 + 公式 + 防错规则。<strong>示例数据一定要它标&quot;假数据&quot;</strong>，避免你误当成真实案例。</p><hr><h2 id="_5-·-零散产出-→-一页纸周报" tabindex="-1">5 · 零散产出 → 一页纸周报 <a class="header-anchor" href="#_5-·-零散产出-→-一页纸周报" aria-label="Permalink to &quot;5 · 零散产出 → 一页纸周报&quot;">​</a></h2><p><strong>什么时候用</strong>：周五下午。你这周干了一堆事，但都是碎的：几个文件、几条消息、几件没做完的。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这是我这一周零散的产出（想到什么写什么，不用整理）：</span></span>
<span class="line"><span>【罗列：做了什么 / 做完了什么 / 卡在哪 / 下周要做什么】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我整理成一页纸周报，结构：</span></span>
<span class="line"><span>① 本周完成（每条开头用动词，一句话说结果，带数字更好）</span></span>
<span class="line"><span>② 进行中（写清楚卡点和下一步）</span></span>
<span class="line"><span>③ 需要支持（明确写要谁做什么）</span></span>
<span class="line"><span>④ 下周计划（不超过 3 条）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>规矩：不要拔高、不要用&quot;赋能、闭环、抓手&quot;这类词；没做的不许写。</span></span></code></pre></div><p><strong>它给你</strong>：一页纸周报。<strong>&quot;不要拔高&quot;和&quot;没做的不许写&quot;这两句，是这份提示词的全部价值</strong>。</p><hr><h2 id="💡-这-5-条为什么长这样" tabindex="-1">💡 这 5 条为什么长这样 <a class="header-anchor" href="#💡-这-5-条为什么长这样" aria-label="Permalink to &quot;💡 这 5 条为什么长这样&quot;">​</a></h2><p>三条通用规律，你可以拿去改任何一条：</p><ol><li><strong>一定写清交付物的形状</strong>（结构、条目数、长度）——不写，它就会给你一大段你还要自己拆的话。</li><li><strong>一定加一句&quot;不要替我补&quot;</strong>——AI 最大的坑不是写不好，是<strong>编得很自然</strong>。</li><li><strong>一定要一个&quot;先给方案，我确认再动&quot;的中间步骤</strong>——凡是涉及改你的文件、发出去的东西，都留一道闸。</li></ol><hr><p><strong>目录</strong>：<a href="/MoMAWork-/community/prompts/">← 回到行业提示词模板库</a> ｜ 下一个行业 → <strong><a href="/MoMAWork-/community/prompts/电商与直播.html">电商与直播带货</a></strong></p>`,35)])])}const u=a(e,[["render",l]]);export{g as __pageData,u as default};
